/** Stored path on the multi-path incoming messages. Later routes are `messageRepeats(messageID, now)`. */
internal val MockDataProvider.pinnedIncomingFirstPath: Bytes
    get() = Bytes.of(northRidgeRepeaterSeed.toInt(), twinPeaksRepeaterSeed.toInt())

internal const val PINNED_INCOMING_EXTRA_PATH_COUNT = 3

internal const val PINNED_ALICE_MULTI_PATH_AGE_SECONDS = -40L
internal const val PINNED_PUBLIC_MULTI_PATH_AGE_SECONDS = -20L

internal fun MockDataProvider.pinnedAliceMultiPathMessage(now: Instant, senderKey: Bytes): MessageDTO =
    PinnedMockMessageFactory.message(
        id = aliceMultiPathMessageID,
        createdAt = now.addingInterval(PINNED_ALICE_MULTI_PATH_AGE_SECONDS),
        text = "Still on the trail. This one came in a few different ways.",
        direction = MessageDirection.INCOMING,
        contactID = aliceChenID,
        pathLength = encodePathLen(hashSize = 1, hopCount = 2),
        snr = 9.1,
        pathNodes = pinnedIncomingFirstPath,
        senderKeyPrefix = senderKey,
        isRead = false,
        heardRepeats = PINNED_INCOMING_EXTRA_PATH_COUNT.toLong(),
        routeType = RouteType.FLOOD,
    )

